-- ── story 9-3a: the audit trail and ledger navigation ──────────────────────
-- Generated by drizzle-kit (the two `ledger_event_id` columns, the audit
-- index swap) and hand-amended below the marker with the five partial
-- expression indexes on `ledger_events`, which drizzle-kit cannot model (the
-- 0039 precedent: they are not in schema.ts or the snapshot, so the next
-- `bun run db:generate` does not re-emit them; it reports "No schema changes").
--
-- Additive and index-only apart from two NULLABLE columns: no table, no data
-- statement (so no pre-flight and no fail-fast guard), no CHECK — so there is
-- nothing to probe (IMPLEMENTATION-GUIDE §3), and no RLS change (both tables
-- already carry their policies). The columns are written going forward only:
-- a pending adjustment or count variance decided before 9-3a stays NULL and
-- shows no ledger link (no backfill — story decision).
--
--   audit_events: the read pages on created_at (the server stamp), so the
--     old (tenant_id, occurred_at) index — which nothing reads — is dropped
--     and replaced by the read's four shapes.
--   ledger_events: one partial btree per document key the ledger list now
--     filters on, `(tenant_id, warehouse_id, (reference_doc ->> key)) WHERE
--     reference_doc ? key`; the read carries the `?` predicate so the planner
--     can prove the partial index applies.
--
-- DEPLOY NOTE: drizzle's migrator applies every pending migration in ONE
-- transaction, so CREATE INDEX CONCURRENTLY is impossible here — each index
-- build takes a SHARE lock that blocks writes to its table (ledger_events:
-- every stock movement) for the build's duration. Size when written
-- (2026-10-12): no production database exists yet; the dev database's
-- ledger_events holds 147 rows / 384 kB (audit_events 301 rows / 168 kB), so
-- the builds take milliseconds. Against a large live ledger, schedule the
-- deploy in a quiet window or pre-build the five ledger indexes
-- CONCURRENTLY by hand under these exact names first (CREATE INDEX IF NOT
-- EXISTS below then skips them) — the reporting runbook in PENDING.md.
DROP INDEX "audit_events_tenant_id_occurred_at_idx";--> statement-breakpoint
ALTER TABLE "count_variances" ADD COLUMN "ledger_event_id" uuid;--> statement-breakpoint
ALTER TABLE "stock_adjustment_pendings" ADD COLUMN "ledger_event_id" uuid;--> statement-breakpoint
CREATE INDEX "audit_events_tenant_created_idx" ON "audit_events" USING btree ("tenant_id","created_at" DESC NULLS LAST,"id" DESC NULLS LAST);--> statement-breakpoint
CREATE INDEX "audit_events_tenant_actor_created_idx" ON "audit_events" USING btree ("tenant_id","actor_user_id","created_at" DESC NULLS LAST);--> statement-breakpoint
CREATE INDEX "audit_events_tenant_target_idx" ON "audit_events" USING btree ("tenant_id","target_type","target_id");--> statement-breakpoint
CREATE INDEX "audit_events_tenant_action_created_idx" ON "audit_events" USING btree ("tenant_id","action" text_pattern_ops,"created_at" DESC NULLS LAST);
--> statement-breakpoint
-- ── hand-amended below: the ledger document-key indexes ─────────────────────
CREATE INDEX IF NOT EXISTS "ledger_events_grn_ref_idx" ON "ledger_events" USING btree ("tenant_id","warehouse_id",("reference_doc"->>'grnId')) WHERE "reference_doc" ? 'grnId';--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "ledger_events_po_ref_idx" ON "ledger_events" USING btree ("tenant_id","warehouse_id",("reference_doc"->>'poId')) WHERE "reference_doc" ? 'poId';--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "ledger_events_transfer_ref_idx" ON "ledger_events" USING btree ("tenant_id","warehouse_id",("reference_doc"->>'transferId')) WHERE "reference_doc" ? 'transferId';--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "ledger_events_adjustment_pending_ref_idx" ON "ledger_events" USING btree ("tenant_id","warehouse_id",("reference_doc"->>'adjustmentPendingId')) WHERE "reference_doc" ? 'adjustmentPendingId';--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "ledger_events_count_variance_ref_idx" ON "ledger_events" USING btree ("tenant_id","warehouse_id",("reference_doc"->>'countVarianceId')) WHERE "reference_doc" ? 'countVarianceId';
